

function signSealSignature(){
    var code=`new HebcaMiddleware.Seal({   /*创建签章对象*/
    context: 'default-stand-alone',    /*设置签章环境，这里以单机版举例，可以设置其它环境*/
    success:function (s) {
        /*整体签章*/
        s.signSealSignature({
            data: "12345678",   /*原文*/
            show: {             /*签章显示相关设置*/
                divId:"seal",   /*指定显示的div*/
                ui: HebcaMiddleware.uiBootstrap   /*指定UI界面实现*/
            },
            success: function (sealSignature){
                /*获取签章结果*/
                alert(sealSignature)
            },
            fail:function (e){
                alert(e.message)
            }
        })
    },
    fail:function (e) {
        alert(e.message)
    }
})`
    showCode('code',code)
}

function signSealSignatureSeq(){
    var code=`var seq=new HebcaMiddleware.Seq()
seq.then(function (){
    /*创建签章对象*/
    new HebcaMiddleware.Seal({
        context: 'default-stand-alone',  /*设置签章环境，这里以单机版举例，可以设置其它环境*/
        success:function (s){
            seq.resolve(s)
        },
        fail:function (e){
            seq.reject(e)
        }
    })
}).then(function (seq,s){
    /*整体签章*/
    s.signSealSignature({
        data: "12345678",   /*原文*/
        show: {            /*签章显示相关设置*/
            divId:"seal_seq",  /*指定显示的div*/
            ui: HebcaMiddleware.uiBootstrap /*指定UI界面实现*/
        },
        success: function (sealSignature){
            /*获取签章结果*/
            alert(sealSignature)
        },
        fail:function (e){
            alert(e.message)
        }
    })
}).onerror(function (e){
    alert(e.message)
}).run()`

    showCode('code_seq',code)
}

function signSealSignaturePromise(){
    var code=`HebcaMiddlewareX.createSeal({   /*创建签章对象*/
    context: 'default-stand-alone',    /*设置签章环境，这里以单机版举例，可以设置其它环境*/
}).then(s=>{
    /*整体签章*/
    return s.signSealSignature({
        data:"12345678",   /*原文*/
        show: {      /*签章显示相关设置*/
            divId:"seal_promise",   /*指定显示的div*/
            ui: HebcaMiddleware.uiBootstrap  /*指定UI界面实现*/
        },
    })
}).then(sealSignature=>{
    /*获取签章结果*/
    alert(sealSignature)
}).catch(e=>{
    alert(e.message)
})`

    showCode('code_promise',code)
}

